import sqlite3
import json
import ast
from collections import defaultdict
from typing import Any, Dict, List, Optional, Tuple

# Milvus
from pymilvus import connections, Collection, utility


# =========================
# Fixed configuration (as required)
# =========================
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# =========================
# Helpers
# =========================
def parse_attributes(raw: Any) -> Dict[str, Any]:
    """Parse Yelp 'attributes' field robustly.

    Common cases:
    - NULL/None
    - JSON string (double quotes)
    - Python dict-like string (single quotes)
    - Already a dict
    """
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return raw

    s = str(raw).strip()
    if not s or s.lower() == 'none' or s.lower() == 'null':
        return {}

    # Try JSON
    try:
        return json.loads(s)
    except Exception:
        pass

    # Try python literal (handles single quotes dict)
    try:
        val = ast.literal_eval(s)
        if isinstance(val, dict):
            return val
    except Exception:
        pass

    return {}


def truthy(v: Any) -> bool:
    if v is True:
        return True
    if v is False or v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        x = v.strip().lower()
        return x in {"true", "1", "yes", "y"}
    return False


def normalize_wifi(v: Any) -> Optional[str]:
    if v is None:
        return None
    if isinstance(v, str):
        x = v.strip().lower()
        # Yelp sometimes stores as 'free', 'paid', 'no' or 'u' variants
        return x
    return str(v).strip().lower()


def chunked(lst: List[Any], n: int) -> List[List[Any]]:
    return [lst[i:i+n] for i in range(0, len(lst), n)]


# =========================
# Step 1-3: SQLite queries
# =========================
def fetch_franklin_coffee_candidates() -> List[Tuple]:
    """Return rows: (business_id, name, city, state, categories, attributes, stars, review_count)."""
    conn = sqlite3.connect(sqlite_paths["business"])
    try:
        cur = conn.cursor()
        # Broad coffee match; you can expand patterns if needed
        sql = """
        SELECT business_id, name, city, state, categories, attributes, stars, review_count
        FROM business
        WHERE city = ?
          AND categories LIKE ?
        """
        cur.execute(sql, ("Franklin", "%Coffee%"))
        return cur.fetchall()
    finally:
        conn.close()


def filter_by_outdoor_and_free_wifi(biz_rows: List[Tuple]) -> List[Dict[str, Any]]:
    filtered = []
    for (business_id, name, city, state, categories, attributes, stars, review_count) in biz_rows:
        attrs = parse_attributes(attributes)
        outdoor = attrs.get("OutdoorSeating")
        wifi = attrs.get("WiFi")

        if truthy(outdoor) and normalize_wifi(wifi) == "free":
            filtered.append({
                "business_id": business_id,
                "name": name,
                "city": city,
                "state": state,
                "categories": categories,
                "stars": stars,
                "review_count": review_count,
                "attributes": attrs,
            })
    return filtered


def fetch_inside_and_drink_photos(business_ids: List[str]) -> List[Tuple]:
    """Return rows: (photo_id, business_id, label, caption)."""
    if not business_ids:
        return []

    conn = sqlite3.connect(sqlite_paths["photo"])
    try:
        cur = conn.cursor()

        # Avoid SQLite parameter limit issues by chunking
        out = []
        for ids in chunked(business_ids, 900):
            placeholders = ",".join(["?"] * len(ids))
            sql = f"""
            SELECT photo_id, business_id, label, caption
            FROM photo
            WHERE business_id IN ({placeholders})
              AND label IN ('inside','drink')
            """
            cur.execute(sql, ids)
            out.extend(cur.fetchall())
        return out
    finally:
        conn.close()


# =========================
# Step 4: (Optional) Milvus enrich
# =========================
def try_enrich_photos_from_milvus(photo_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    """Attempt to fetch extra fields for each photo_id from Milvus 'photo_vector' collection.

    Returns mapping: photo_id -> extra_fields
    If Milvus/collection/fields not available, returns empty dict.
    """
    if not photo_ids:
        return {}

    collection_name = milvus_config['milvus_collections']['photos']

    try:
        connections.connect(alias="default", host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])
    except Exception:
        return {}

    try:
        if not utility.has_collection(collection_name):
            return {}

        col = Collection(collection_name)
        schema_fields = [f.name for f in col.schema.fields]

        # Determine the id field name. Common choices: 'photo_id', 'id', or primary key.
        # We'll prefer 'photo_id' if present.
        if "photo_id" in schema_fields:
            id_field = "photo_id"
        else:
            # Fallback to primary key field if any
            pk_fields = [f.name for f in col.schema.fields if getattr(f, "is_primary", False)]
            id_field = pk_fields[0] if pk_fields else None

        if not id_field:
            return {}

        # Output fields to attempt (only those that exist)
        candidate_fields = [
            "photo_id", "business_id", "image_path", "path", "uri", "url", "caption", "label"
        ]
        output_fields = [f for f in candidate_fields if f in schema_fields and f != "embedding"]

        if not output_fields:
            return {}

        # Query in chunks
        enriched: Dict[str, Dict[str, Any]] = {}
        for ids in chunked(photo_ids, 200):
            # Milvus expr expects string quotes for varchar fields
            quoted = ",".join([f'"{x}"' for x in ids])
            expr = f"{id_field} in [{quoted}]"
            rows = col.query(expr=expr, output_fields=output_fields)
            for r in rows:
                pid = r.get("photo_id") or r.get(id_field)
                if pid is not None:
                    enriched[str(pid)] = r
        return enriched

    except Exception:
        return {}


# =========================
# Main execution
# =========================
def main(limit_businesses: Optional[int] = None, limit_photos_per_label: int = 5):
    # Step 1
    biz_rows = fetch_franklin_coffee_candidates()

    # Step 2
    filtered_biz = filter_by_outdoor_and_free_wifi(biz_rows)

    if limit_businesses is not None:
        filtered_biz = filtered_biz[:limit_businesses]

    business_ids = [b["business_id"] for b in filtered_biz]

    # Step 3
    photo_rows = fetch_inside_and_drink_photos(business_ids)

    # Group photos by business_id + label
    photos_by_biz: Dict[str, Dict[str, List[Dict[str, Any]]]] = defaultdict(lambda: {"inside": [], "drink": []})
    all_photo_ids = []
    for (photo_id, business_id, label, caption) in photo_rows:
        all_photo_ids.append(str(photo_id))
        label_norm = (label or "").strip().lower()
        if label_norm not in ("inside", "drink"):
            continue
        photos_by_biz[business_id][label_norm].append({
            "photo_id": str(photo_id),
            "label": label_norm,
            "caption": caption
        })

    # Optional Step 4: try enrich from Milvus
    milvus_enrich = try_enrich_photos_from_milvus(all_photo_ids)
    if milvus_enrich:
        for biz_id, buckets in photos_by_biz.items():
            for label in ("inside", "drink"):
                for p in buckets[label]:
                    extra = milvus_enrich.get(p["photo_id"])
                    if extra:
                        # Attach only non-null extra fields
                        p["milvus"] = {k: v for k, v in extra.items() if v is not None}

    # Build final output
    results = []
    for b in filtered_biz:
        biz_id = b["business_id"]
        inside = photos_by_biz[biz_id]["inside"][:limit_photos_per_label]
        drink = photos_by_biz[biz_id]["drink"][:limit_photos_per_label]
        results.append({
            "business_id": biz_id,
            "name": b["name"],
            "city": b["city"],
            "state": b["state"],
            "stars": b["stars"],
            "review_count": b["review_count"],
            "categories": b["categories"],
            "requirements": {
                "OutdoorSeating": True,
                "WiFi": "free"
            },
            "photos": {
                "inside": inside,
                "drink": drink
            }
        })

    # Print as JSON
    print(json.dumps({
        "query_city": "Franklin",
        "category_match": "%Coffee%",
        "matched_business_count": len(results),
        "businesses": results
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    # You can tweak limits for faster iteration.
    main(limit_businesses=None, limit_photos_per_label=5)

